class Solution {
public:
    int largestPalindrome(int n) {
        if (n == 1) return 9;
        long long upper = 1;
        for (int i = 0; i < n; ++i) upper *= 10;
        long long lower = upper / 10;
        --upper;
        for (long long left = upper; left >= lower; --left) {
            std::string a = std::to_string(left);
            std::string b = a;
            std::reverse(b.begin(), b.end());
            long long pal = std::stoll(a + b);
            for (long long factor = upper; factor * factor >= pal; --factor) {
                if (pal % factor == 0 && pal / factor >= lower &&
                    pal / factor <= upper) return pal % 1337;
            }
        }
        return -1;
    }
};
